{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C168","C145","C183","C163","C160","C25","C32","C40","C54","C242","C261","C265","C286","C289","C254"],
  "contradictory_card_ids": ["C250","C245","C275","C12","C08"],
  "prediction_basis_card_ids": ["C168","C145","C183","C163","C160","C242","C261","C265","C286","C289","C254","C25","C32","C40","C54"],
  "claims": [
    {
      "claim": "The query is a highly lipophilic retinamide (logP 6.86) with a phenol; L4 measured aqueous solubilities of close retinoid analogs are extremely low (etretinate 3.4 nM, N-ethyl retinamide 23.5 nM, motretinid 6.5 nM, tretinoin 0.19 µg/mL and insoluble in water), indicating a severe dissolution liability for this scaffold.",
      "card_ids": ["C168","C145","C183","C163","C160"]
    },
    {
      "claim": "L6 hepatic metabolism records show that the retinoic acid scaffold is oxidized by multiple CYPs (CYP2C8, CYP3A4, CYP3A5, CYP3A7, CYP26) and glucuronidated by UGT1A8/2B7, providing mechanistic support for first-pass loss in a retinoid-like molecule; no fenretinide-specific hepatic clearance measurement is present.",
      "card_ids": ["C242","C261","C265","C286","C289","C254"]
    },
    {
      "claim": "L2 low-F contexts for high-logP polyene/amide molecules (zeaxanthin extremely low in rats; apatinib 10-20% and 9-15% in dogs) support that such lipophilic molecules can fall below the 20% threshold, though transferability is limited.",
      "card_ids": ["C25","C32","C40","C54"]
    },
    {
      "claim": "Metabolic-stability records for all-trans-retinoic acid (HLM stability, HepG2 half-life ~23 h) and positive qualitative outcomes for zeaxanthin in egg yolk and apatinib are not query-specific and do not outweigh the solubility and retinoid-metabolism evidence.",
      "card_ids": ["C250","C245","C275","C12","C08"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C242","C261","C265","C286","C289","C254"]
    }
  ],
  "evidence_gaps": [
    "No fenretinide-specific absolute oral bioavailability or matched oral vs IV AUC measurement is present.",
    "No fenretinide-specific solubility, permeability, efflux, intestinal metabolism, or hepatic clearance measurement is present; L4/L5/L6 data are for close analogs or unrelated molecules.",
    "Query formulation is unknown; lipid-based or surfactant formulations could improve dissolution (e.g., lutein SNEDDS ~90% release, tretinoin surfactant solubility).",
    "First-pass hepatic metabolism of fenretinide specifically (e.g., phenol glucuronidation, amide hydrolysis) is unmeasured.",
    "L6 records are for retinoic acid and other molecules, not fenretinide; transferability is limited by the amide/phenol differences."
  ],
  "decision_summary": "L6 hepatic clearance/metabolic stability records show extensive CYP- and UGT-mediated metabolism of the retinoic acid scaffold, providing low-transferability mechanistic support for presystemic loss in this retinamide. Combined with L4 close-retinoid solubility measurements and L2 low-F lipophilic contexts, the evidence better supports F < 20%; prediction remains low with moderate confidence."
}

